/**
 * Diagram identity, lineage and relationships (docs/DIAGRAMS.md, "the lineage rule").
 *
 * Every diagram source (docs/diagrams/*.mmd and every ```mermaid block of the repo's Markdown) carries one header, a
 * single-line comment on the line after the theme's init line:
 *
 *   %% kit:diagram {"id":"saasreport.terminal.arch","title":"…","project":"saasreport","kind":"architecture",
 *                   "lineage":{"derives_from":[],"supersedes":[],"version":"1"},"relates_to":[],"depicts":[],"reviewed":"2026-10-06"}
 *
 * The header is JSON validated by the bundled schema `diagram` (kit.diagram.v1). Everything below is a pure function of the
 * headers: the checks (`lineageProblems`), the generated index docs/diagrams/README.md (`generateIndex`), the generated lineage
 * graph docs/diagrams/lineage.mmd (`generateLineage`) and the best-effort `migrate`. Nothing here invents a relationship.
 */
import { existsSync, readFileSync, realpathSync, statSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { join, relative, basename, posix } from "node:path";
import { formatProblems } from "@saasreport/core/schema";
import { bundled } from "./bundled.js";
import { DIAGRAM_DIR, applyTheme, badMermaidFences, markdownFiles, mermaidBlocks, mmdFiles, readStamp, readStampId, sourceHash, pngOf, checkRepo as checkThemeRepo, loadTheme } from "./diagrams.js";
import { headerLine, readHeader, withHeader } from "./diagram-header.js";
import { orphanPngs, pairingProblems } from "./diagram-pairing.js";
import { gitEnv } from "./git.js";
import { foreignProjectRefs } from "./diagram-themes.js";
export { readHeader, headerLine, withHeader };

export const INDEX_FILE = `${DIAGRAM_DIR}/README.md`;
export const LINEAGE_FILE = `${DIAGRAM_DIR}/lineage.mmd`;
export const EXTERNALS_FILE = `${DIAGRAM_DIR}/externals.json`;
export const GENERATED_MARK = "<!-- Generated by `kit diagrams render` from the `%% kit:diagram` headers of the diagram sources. Never edit by hand. -->";

// ---- the project code ----

/** The project code of a registry key: the `short` without its dash (saasreport → saasreport), the key itself when there is none, kit for the kit. */
export function projectCode(key, registry = bundled().registry) {
  if (key === "kit") return "kit";
  const p = registry.projects.find((x) => x.key === key);
  if (!p) return null;
  return p.short ? p.short.replace(/-$/, "") : p.key;
}

/** { key, code } of the repo at root from its kit.canon.json `project`, or from `override` (a key or a code). */
export function projectOf(root, override, registry = bundled().registry) {
  let key = override;
  if (!key) {
    const f = join(root, "kit.canon.json");
    if (existsSync(f)) { try { key = JSON.parse(readFileSync(f, "utf8")).project; } catch { /* reported by kit check canon */ } }
  }
  if (!key) return null;
  const direct = projectCode(key, registry);
  if (direct) return { key, code: direct };
  const byCode = registry.projects.find((p) => (p.short || "").replace(/-$/, "") === key);
  if (byCode) return { key: byCode.key, code: key };
  return null;   // a code the registry does not hold is no project: the registry is the one list (packages/core/scripts/project-codes.mjs generates the schemas from it)
}

// ---- collecting ----

/**
 * Every diagram source of the repo: docs/diagrams/*.mmd and the mermaid blocks of its Markdown files.
 * → [{ file, block (1-based, or null), where (display), source, header, error, mmd }]
 */
export function collectDiagrams(root) {
  const out = [];
  for (const f of mmdFiles(root)) {
    const source = readFileSync(join(root, f), "utf8");
    out.push({ file: f, block: null, where: f, source, mmd: true, ...readHeader(source) });
  }
  for (const f of markdownFiles(root)) {
    const text = readFileSync(join(root, f), "utf8");
    mermaidBlocks(text).forEach((b, i) => {
      out.push({ file: f, block: i + 1, where: `${f} (mermaid block ${i + 1})`, source: b.body, mmd: false, offset: b.start, ...readHeader(b.body) });
    });
  }
  return out;
}

/** The declared external ids: [{ repo, ids }] from docs/diagrams/externals.json ({ externals, problems }). */
export function loadExternals(root, kit = bundled()) {
  const f = join(root, EXTERNALS_FILE);
  if (!existsSync(f)) return { externals: [], problems: [] };
  let doc;
  try { doc = JSON.parse(readFileSync(f, "utf8")); } catch (e) { return { externals: [], problems: [{ file: EXTERNALS_FILE, problem: `not valid JSON (${e.message})` }] }; }
  const problems = formatProblems(kit.validator.validate(doc, kit.byName("diagram-externals"))).map((p) => ({ file: EXTERNALS_FILE, problem: p }));
  return { externals: problems.length ? [] : doc.externals, problems };
}

// ---- checks ----

/** The Mermaid body of a diagram source without any `%%` line (init, header, comments), blank lines and trailing blanks. */
export const mermaidBody = (source) => source.replace(/\r\n/g, "\n").split("\n").filter((l) => l.trim() && !/^\s*%%/.test(l)).map((l) => l.trimEnd()).join("\n");

/** The repository's tracked files (a Set) when root is a git work tree, else null. */
function trackedFiles(root) {
  const g = spawnSync("git", ["ls-files", "-z"], { cwd: root, encoding: "utf8", maxBuffer: 1 << 28, env: gitEnv() });
  return g.status === 0 ? new Set(g.stdout.split("\0").filter(Boolean)) : null;
}

/**
 * Why a `depicts` path is not acceptable (null when it is): it must be a file or a directory inside the repository (a symlink that
 * resolves outside is rejected) and, in a git work tree, tracked (not untracked or ignored).
 */
export function depictsProblem(root, path, tracked) {
  if (path.startsWith("/") || path.split("/").includes("..")) return "is not a path inside the repository";
  const abs = join(root, path);
  if (!existsSync(abs)) return "does not exist";
  let real;
  try { real = realpathSync(abs); } catch { return "does not resolve"; /* the reason is the problem reported for this path */ }
  const rootReal = realpathSync(root);
  if (real !== rootReal && !real.startsWith(`${rootReal}/`)) return "resolves outside the repository (a symlink)";
  const st = statSync(real);
  if (!st.isFile() && !st.isDirectory()) return "is neither a file nor a directory";
  if (tracked) {
    const p = path.replace(/\/+$/, "");
    const hit = tracked.has(p) || (st.isDirectory() && [...tracked].some((t) => t.startsWith(`${p}/`)));
    if (!hit) return "is not tracked by git (an untracked or ignored path cannot be what a diagram depicts)";
  }
  return null;
}

function cycles(edges) {
  const found = [], state = new Map();
  const visit = (n, path) => {
    state.set(n, 1);
    for (const m of edges.get(n) || []) {
      if (state.get(m) === 1) found.push([...path.slice(path.indexOf(m)), m, ]);
      else if (!state.has(m)) visit(m, [...path, m]);
    }
    state.set(n, 2);
  };
  for (const n of [...edges.keys()].sort()) if (!state.has(n)) visit(n, [n]);
  return found;
}

/**
 * The lineage rule against the headers: missing or invalid header, duplicate id, id prefix, dangling references, cycles in
 * derives_from and supersedes, depicts paths that do not exist. → { problems: [{ file, problem }], ids, externalIds }
 * (every header is complete or the diagram fails: there is no stub state and no warning level).
 */
export function lineageProblems(root, entries, { code, kit = bundled() } = {}) {
  const problems = [];
  const P = (file, problem) => problems.push({ file, problem });
  const ext = loadExternals(root, kit);
  problems.push(...ext.problems);
  const externalIds = new Set(ext.externals.flatMap((e) => e.ids));
  const ids = new Map();
  for (const e of entries) {
    if (e.error) { P(e.where, e.error); continue; }
    if (!e.header) { P(e.where, "no `%% kit:diagram {…}` header (every diagram carries id, lineage and relationships: the author writes the whole header; kit diagrams migrate lists the diagrams without one)"); continue; }
    const bad = formatProblems(kit.validator.validate(e.header, kit.byName("diagram")));
    for (const b of bad) P(e.where, `header ${b}`);
    if (bad.length) continue;
    const h = e.header;
    // the header's project is any registered project: the theme it selects (or its refusal) is the diagram check's, not this rule's
    if (!h.id.startsWith(`${h.project}.`)) P(e.where, `id ${h.id} must start with its project code "${h.project}."`);
    if (ids.has(h.id)) P(e.where, `duplicate id ${h.id} (also ${ids.get(h.id)})`);
    else ids.set(h.id, e.where);
    if (h.generated && !(e.mmd && e.file === LINEAGE_FILE)) P(e.where, "`generated` belongs only to docs/diagrams/lineage.mmd");
  }
  const known = (id) => ids.has(id) || externalIds.has(id);
  const byId = new Map(entries.filter((e) => e.header && !e.error).map((e) => [e.header.id, e]));
  const tracked = trackedFiles(root);
  const derives = new Map(), supersedes = new Map();
  for (const e of entries) {
    const h = e.header;
    if (!h || e.error) continue;
    const refs = [
      ...(h.lineage?.derives_from || []).filter((r) => !r.startsWith("https://")).map((r) => ["derives_from", r]),
      ...(h.lineage?.supersedes || []).map((r) => ["supersedes", r]),
      ...(h.relates_to || []).map((r) => ["relates_to", r?.id]),
    ];
    for (const [field, ref] of refs) {
      if (typeof ref !== "string") continue;
      if (ref === h.id) P(e.where, `${field} refers to the diagram itself (${ref})`);
      else if (!known(ref)) P(e.where, `${field}: ${ref} is not a diagram of this repository nor declared in ${EXTERNALS_FILE} (dangling reference)`);
    }
    derives.set(h.id, (h.lineage?.derives_from || []).filter((r) => ids.has(r) && r !== h.id));
    supersedes.set(h.id, (h.lineage?.supersedes || []).filter((r) => ids.has(r) && r !== h.id));
    for (const f of foreignProjectRefs(h, kit.registry)) P(e.where, `${f.field} "${f.text}" points into ${f.repo}, a repository of project ${f.project}, but the header's project is ${h.project}: a ${f.project} diagram is drawn in ${f.project}'s colours (header project "${f.project}", id ${f.project}.…), never in ${h.project}'s`);
    for (const d of h.depicts || []) {
      if (typeof d?.path !== "string") continue;
      const bad = depictsProblem(root, d.path, tracked);
      if (bad) P(e.where, `depicts ${d.kind} ${d.ref}: path ${d.path} ${bad}`);
    }
    // derives_from means a copy of the same content: the parent's Mermaid body (comment lines aside) is this one's
    for (const r of h.lineage?.derives_from || []) {
      const parent = byId.get(r);
      if (!parent || !e.source || !parent.source || parent.header?.generated) continue;
      if (mermaidBody(parent.source) !== mermaidBody(e.source)) P(e.where, `derives_from ${r}, but the Mermaid body differs: derives_from means a copy of the same content, regenerated from the parent (kit diagrams render does it). For a related diagram use relates_to (zooms-into, sibling, depends-on…) or supersedes`);
    }
  }
  // one graph: a derives_from edge A -> B and a supersedes edge B -> A are as much a cycle as two derives_from edges
  const combined = new Map();
  for (const id of ids.keys()) combined.set(id, [...(derives.get(id) || []), ...(supersedes.get(id) || [])]);
  for (const c of cycles(combined)) P(ids.get(c[0]) || c[0], `cycle in derives_from / supersedes: ${c.join(" -> ")}`);
  return { problems, ids, externalIds };
}

// ---- generated: the lineage graph and the index ----

const q = (s) => String(s).replace(/"/g, "'");

/** The header of the generated lineage graph. */
export function lineageHeader(code) {
  return {
    id: `${code}.diagrams.lineage`, title: "Diagram lineage", project: code, kind: "other",
    summary: "Every diagram of this repository and how they derive from, supersede and relate to one another; generated from the diagram headers.",
    lineage: { derives_from: [], supersedes: [], version: "1" }, relates_to: [],
    depicts: [{ kind: "doc", ref: "the diagram headers", path: DIAGRAM_DIR }], generated: true,
  };
}

/** The islands (connected components) of an edge list, each with its nodes sorted, its first root and its deepest node. */
function islands(edges, nodes) {
  const adj = new Map(nodes.map((n) => [n, new Set()]));
  for (const [a, b] of edges) { adj.get(a)?.add(b); adj.get(b)?.add(a); }
  const seen = new Set(), out = [];
  for (const n of [...nodes].sort()) {
    if (seen.has(n)) continue;
    const comp = [], todo = [n];
    seen.add(n);
    while (todo.length) { const x = todo.pop(); comp.push(x); for (const y of adj.get(x)) if (!seen.has(y)) { seen.add(y); todo.push(y); } }
    comp.sort();
    const inc = new Map(comp.map((c) => [c, 0]));
    for (const [a, b] of edges) if (inc.has(b) && inc.has(a) && a !== b) inc.set(b, inc.get(b) + 1);
    const depth = new Map(comp.map((c) => [c, 0]));
    for (let i = 0; i < comp.length; i++) for (const [a, b] of edges) if (depth.has(a) && depth.has(b) && a !== b && depth.get(b) < depth.get(a) + 1 && depth.get(a) < comp.length) depth.set(b, depth.get(a) + 1);
    const root = comp.find((c) => inc.get(c) === 0) || comp[0];
    const deepest = [...comp].sort((x, y) => depth.get(y) - depth.get(x) || x.localeCompare(y))[0];
    out.push({ root, deepest });
  }
  return out;
}
const stackIslands = (edges, nodes) => { const is = islands(edges, nodes); return is.slice(1).map((c, i) => [is[i].deepest, c.root]); };
const lastDeepest = (edges, nodes) => islands(edges, nodes).at(-1).deepest;

/**
 * docs/diagrams/lineage.mmd: derives_from (solid arrow, parent → derived), supersedes (dotted, new → old), relates_to (labelled).
 * Diagrams still needing review are dashed; external ids are drawn as such; diagrams without any relation are grouped in
 * columns so the picture stays top-to-bottom. `entries`: the diagrams with a valid header (the generated one excluded).
 */
export function generateLineage(entries, theme, code) {
  const all = entries.filter((e) => e.header && !e.header.generated).map((e) => e.header).sort((a, b) => a.id.localeCompare(b.id));
  // A pure copy (derives_from a local parent, no other relation, referred to by nobody) is folded into its parent's label, so a
  // repository of many generated copies stays a readable picture.
  const referred = new Set(all.flatMap((h) => [...h.lineage.derives_from, ...h.lineage.supersedes]));
  const ids = new Set(all.map((h) => h.id));
  const isCopy = (h) => h.lineage.derives_from.length === 1 && ids.has(h.lineage.derives_from[0]) && !h.lineage.supersedes.length && !referred.has(h.id);
  const copies = new Map();
  for (const h of all) if (isCopy(h)) copies.set(h.lineage.derives_from[0], (copies.get(h.lineage.derives_from[0]) || 0) + 1);
  const heads = all.filter((h) => !isCopy(h));
  const local = new Set(heads.map((h) => h.id));
  const edges = [];   // [from, to, text, style]
  for (const h of heads) {
    for (const r of h.lineage.derives_from) if (!r.startsWith("https://")) edges.push([r, h.id, "", "-->"]);
    for (const r of h.lineage.supersedes) edges.push([h.id, r, "supersedes", "-.->"]);
  }
  const touched = new Set(edges.flatMap((e) => [e[0], e[1]]));
  const node = new Map();
  const nid = (id) => { if (!node.has(id)) node.set(id, `n${node.size + 1}`); return node.get(id); };
  const lines = ["flowchart TB"];
  const connected = [...touched].sort();
  const label = (id) => `${nid(id)}("${q(id)}${copies.get(id) ? ` · ${copies.get(id)} cop${copies.get(id) === 1 ? "y" : "ies"}` : ""}")`;
  for (const id of connected) lines.push(`  ${label(id)}`);
  const sorted = [...edges].sort((a, b) => `${a[0]} ${a[1]} ${a[3]} ${a[2]}`.localeCompare(`${b[0]} ${b[1]} ${b[3]} ${b[2]}`));
  const seen = new Set();
  for (const [a, b, text, style] of sorted) {
    const l = `  ${nid(a)} ${style}${text ? `|${text}|` : ""} ${nid(b)}`;
    if (!seen.has(l)) { seen.add(l); lines.push(l); }
  }
  const alone = heads.filter((h) => !touched.has(h.id)).map((h) => h.id);
  // Related diagrams form islands; left alone they sit side by side and the picture becomes far too wide for a phone. Stack the
  // islands top to bottom with invisible links: the deepest node of one island to the first node of the next.
  const flow = sorted.map((e) => (e[3] === "-.->" ? [e[1], e[0]] : [e[0], e[1]]));   // old -> new, so a supersedes never makes a cycle with derives_from
  const stack = stackIslands(flow, connected);
  for (const [a, b] of stack) lines.push(`  ${nid(a)} ~~~ ${nid(b)}`);
  // diagrams with no lineage edge carry nothing to draw: one node counts them and points to the index (a column of
  // unrelated boxes is a scroll no one reads on a phone)
  if (alone.length) {
    if (stack.length || connected.length) lines.push(`  ${nid(lastDeepest(flow, connected))} ~~~ alone`);
    lines.push(`  alone("${alone.length} diagram${alone.length === 1 ? "" : "s"} with no lineage edges: listed in the index below")`);
  }
  if (!heads.length) lines.push(`  none("No diagrams yet")`);
  for (const id of touched) {
    if (!local.has(id)) lines.push(`  class ${nid(id)} muted`);
  }
  // the brand accent marks what is current: this repository's diagrams at the end of their lineage, which nothing derives from
  // or supersedes (else the first of them, the count of diagrams without lineage, or the empty-state node)
  const onward = new Set(flow.map((e) => e[0]));   // flow runs old -> new: a diagram with an onward edge is not the latest
  const roots = connected.filter((id) => local.has(id) && !onward.has(id));
  const firstLocal = connected.find((id) => local.has(id));
  const marked = roots.length ? roots.map(nid) : firstLocal ? [nid(firstLocal)] : alone.length ? ["alone"] : ["none"];
  lines.push(`  class ${marked.join(",")} accent`);
  for (const [name, def] of theme.classDefs) lines.push(`  classDef ${name} ${def}`);
  return applyTheme(`${theme.init}\n${headerLine(lineageHeader(code))}\n${lines.join("\n")}\n`, theme);
}

const cell = (s) => String(s).replace(/\|/g, "\\|");
const code = (s) => `\`${cell(s)}\``;

/** docs/diagrams/README.md, generated from the headers. */
export function generateIndex(entries, { projectName, lineagePng = true } = {}) {
  const ok = entries.filter((e) => e.header).sort((a, b) => a.header.id.localeCompare(b.header.id) || a.where.localeCompare(b.where));
  const src = (e) => posix.relative(DIAGRAM_DIR, e.file);
  const rows = ok.map((e) => {
    const h = e.header;
    const li = [...(h.lineage?.derives_from || []).map((r) => (r.startsWith("https://") ? `<${r}>` : code(r)))].join("<br>") || "none";
    const sup = (h.lineage?.supersedes || []).map((r) => `supersedes ${code(r)}`);
    const rel = [...sup, ...(h.relates_to || []).map((r) => `${cell(r.relation)} ${code(r.id)}`)].join("<br>") || "none";
    const dep = (h.depicts || []).map((d) => `${cell(d.kind)}: [${cell(d.ref)}](${typeof d.path === "string" ? posix.relative(DIAGRAM_DIR, d.path) : ""})`).join("<br>") || "none";
    const status = h.generated ? " (generated)" : "";
    return `| ${code(h.id)} v${cell(h.lineage?.version ?? "?")} | ${cell(h.title)}${status} | ${h.kind} | ${li} | ${rel} | ${dep} | [${cell(e.block ? `${basename(e.file)} #${e.block}` : basename(e.file))}](${src(e)}) |`;
  });
  const out = [
    GENERATED_MARK, "",
    `# Diagrams: ${projectName || "this repository"}`, "",
    `Every diagram carries a machine-readable header (id, lineage, relationships, what it depicts: [\`kit.diagram.v1\`](../DIAGRAMS.md)). This index and the lineage graph are generated from those headers by \`kit diagrams render\`; \`kit diagrams check\` fails when a header is missing or wrong, a reference dangles, or this page is stale. Each \`.mmd\` source is rendered locally (bundled Mermaid + local Chromium, the theme [\`theme.init\`](theme.init)) to a PNG stamped with its id and source hash, and every image is inspected before it is committed.`, "",
    ...(lineagePng ? ["## Lineage", "", "Solid arrows: derives from (parent to derived). Dotted: supersedes. Relationships (relates to) are in the index below, not drawn: a graph of every relation is wider than a phone. Dashed boxes: ids declared outside this repository. A diagram that is only a generated copy of another (a Markdown block of a .mmd) is folded into its parent as 'n copies'.", "", "![Lineage of every diagram](lineage.png)", "", "Source: [`lineage.mmd`](lineage.mmd)", ""] : []),
    `## Index (${ok.length})`, "",
    "| id | title | kind | derives from | relates to | depicts | source |", "| --- | --- | --- | --- | --- | --- | --- |", ...rows, "",
  ];
  for (const e of ok.filter((x) => x.mmd)) {
    const h = e.header, stem = basename(e.file, ".mmd");
    out.push(`## ${h.id}`, "", `${h.title}${h.summary ? `. ${h.summary}` : ""}`, "", `![${cell(h.title)}](${stem}.png)`, "", `Source: [\`${stem}.mmd\`](${stem}.mmd)`, "");
  }
  return out.join("\n");
}

// ---- derived copies are generated ----

/** `source` with the Mermaid body of `parent` (their init and header lines stay each their own, the body is the parent's, re-indented). */
export function withParentBody(source, parent) {
  const lines = source.replace(/\r\n/g, "\n").split("\n");
  const h = readHeader(source);
  const ph = readHeader(parent);
  if (h.line === undefined || ph.line === undefined) return source;
  const ind = (lines[h.line].match(/^\s*/) || [""])[0];
  const pind = (parent.split("\n")[ph.line].match(/^\s*/) || [""])[0];
  const tail = parent.replace(/\r\n/g, "\n").split("\n").slice(ph.line + 1).map((l) => (l.startsWith(pind) ? l.slice(pind.length) : l)).map((l) => (l ? ind + l : l));
  return [...lines.slice(0, h.line + 1), ...tail].join("\n");
}

/**
 * `derives_from` means a copy of the same content, regenerated from its parent: a diagram whose Mermaid body differs from its
 * (local) parent's gets the parent's body (never hand-edited). Writes the .mmd files and Markdown blocks. → [where] rewritten.
 */
export function syncDerived(root) {
  const entries = collectDiagrams(root);
  const byId = new Map(entries.filter((e) => e.header && !e.error).map((e) => [e.header.id, e]));
  const done = [], edits = new Map();   // file → [{ e, next }]
  for (const e of entries) {
    const h = e.header;
    if (!h || e.error || h.generated) continue;
    for (const r of h.lineage?.derives_from || []) {
      const par = byId.get(r);
      if (!par || par === e || par.header.generated || mermaidBody(par.source) === mermaidBody(e.source)) continue;
      const next = withParentBody(e.source, par.source);
      if (next === e.source) continue;
      if (!edits.has(e.file)) edits.set(e.file, []);
      edits.get(e.file).push({ e, next });
      done.push(e.where);
      break;
    }
  }
  for (const [file, list] of edits) {
    const p = join(root, file);
    if (list[0].e.mmd) { writeFileSync(p, list[0].next); continue; }
    let text = readFileSync(p, "utf8"), shift = 0;
    for (const { e, next } of list.sort((a, b) => a.e.offset - b.e.offset)) {
      text = text.slice(0, e.offset + shift) + next + text.slice(e.offset + shift + e.source.length);
      shift += next.length - e.source.length;
    }
    writeFileSync(p, text);
  }
  return done;
}

// ---- propose (never writes a header) ----

const KIND_BY_SYNTAX = [[/^(sequenceDiagram)\b/, "sequence"], [/^(erDiagram)\b/, "er"], [/^(stateDiagram(-v2)?)\b/, "state"]];
const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, ".").replace(/^\.+|\.+$/g, "");

/** The mermaid syntax's kind where it says one (sequence, er, state); else null: a flowchart is architecture or flow, a person decides. */
function guessKind(source) {
  const body = source.split("\n").map((l) => l.trim()).find((l) => l && !l.startsWith("%%") && !l.startsWith("---"));
  for (const [re, k] of KIND_BY_SYNTAX) if (body && re.test(body)) return k;
  return null;
}

/**
 * The worklist for diagrams without a header: [{ where, suggestedId, project, kind (or null), identicalTo: [{ where, id }], paths: [...] }].
 * It PROPOSES and nothing else: a suggested id from the file name (or file + block), the project, a kind only where the syntax says
 * it, the diagrams (with headers) whose Mermaid body is identical (a candidate `derives_from` parent or a copy) and the repository paths
 * the source mentions (candidate `depicts`). It never writes a header or any file: a repository never holds a half-migrated state.
 * The author writes the real header (all of id, title, project, kind, lineage, relates_to, depicts, reviewed), then runs render.
 */
export function proposeHeaders(root, { code, entries = collectDiagrams(root) } = {}) {
  const taken = new Set(entries.filter((e) => e.header).map((e) => e.header.id));
  const tracked = trackedFiles(root);
  const byBody = new Map();
  for (const e of entries) { const k = mermaidBody(e.source); if (!byBody.has(k)) byBody.set(k, []); byBody.get(k).push(e); }
  const out = [], problems = [];
  for (const e of entries) {
    if (e.header) continue;
    if (e.error) { problems.push({ file: e.where, problem: e.error }); continue; }
    let id;
    if (e.mmd) id = `${code}.${slug(basename(e.file, ".mmd"))}`;
    else id = `${code}.${slug(e.file.replace(/\.md$/i, ""))}.${e.block}`;
    if (taken.has(id)) id = `${id}.2`;
    taken.add(id);
    const same = (byBody.get(mermaidBody(e.source)) || []).filter((x) => x !== e).map((x) => ({ where: x.where, id: x.header?.id || null }));
    const mentioned = [...new Set((e.source.match(/[A-Za-z0-9_.@-]+(?:\/[A-Za-z0-9_.@-]+)+/g) || []).filter((t) => tracked && tracked.has(t)))].slice(0, 12);
    out.push({ where: e.where, suggestedId: id, project: code, kind: guessKind(e.source), identicalTo: same, paths: mentioned });
  }
  return { proposals: out, problems };
}

/** The worklist as Markdown text (stdout or a file outside the repository). */
export function proposalText(proposals) {
  const lines = ["# Headers to write", "", `${proposals.length} diagram${proposals.length === 1 ? "" : "s"} without a \`%% kit:diagram\` header. Nothing was written to the repository.`, "",
    "Write each header yourself: id, title, project, kind, lineage, relates_to, depicts, reviewed (docs/DIAGRAMS.md). Read the diagram and the docs around it; leave a list empty only on purpose.", ""];
  for (const p of proposals) {
    lines.push(`## ${p.where}`, `- suggested id: \`${p.suggestedId}\`  project: \`${p.project}\`${p.kind ? `  kind: \`${p.kind}\` (the syntax says it)` : ""}`);
    if (p.identicalTo.length) lines.push(`- identical Mermaid body: ${p.identicalTo.map((x) => `${x.where}${x.id ? ` (\`${x.id}\`)` : ""}`).join(", ")} (a candidate \`derives_from\` parent or copy)`);
    if (p.paths.length) lines.push(`- repository paths the source mentions (candidate \`depicts\`): ${p.paths.map((x) => `\`${x}\``).join(", ")}`);
    lines.push("");
  }
  return lines.join("\n");
}

// ---- the whole check ----

/** Every diagram's header, with the generated lineage entry present (computed when lineage.mmd is not on disk yet). */
export function entriesWithLineage(root, code) {
  const entries = collectDiagrams(root);
  if (code && !entries.some((e) => e.file === LINEAGE_FILE)) entries.push({ file: LINEAGE_FILE, block: null, where: LINEAGE_FILE, source: "", mmd: true, header: lineageHeader(code) });
  return entries;
}

/**
 * `kit diagrams check`: the theme and PNG-stamp rules (diagrams.js) plus the lineage rule. → { theme, problems, counts, project }. `project`: a registry key or code; default the repo's kit.canon.json `project`.
 */
export function checkDiagrams(root, { project, kit = bundled() } = {}) {
  const base = checkThemeRepo(root, kit);
  const problems = [...base.problems];
  const pr = projectOf(root, project, kit.registry);
  if (!pr) problems.push({ file: "kit.canon.json", problem: "cannot tell the project of this repository (kit.canon.json `project`, or --project): the id prefix cannot be checked" });
  const code = pr?.code;
  const entries = entriesWithLineage(root, code);
  const lp = lineageProblems(root, entries, { code, kit });
  problems.push(...lp.problems);
  for (const o of orphanPngs(root, markdownFiles(root))) problems.push({ file: o, problem: "a PNG under docs/diagrams that no diagram owns (not the sibling of a .mmd, not the image of a paired Markdown block): it cannot be regenerated from a source, so it is not a diagram of this repository" });
  for (const f of markdownFiles(root)) {
    const text = readFileSync(join(root, f), "utf8");
    for (const b of badMermaidFences(text)) problems.push({ file: `${f}:${b.line}`, problem: b.problem });
    if (mermaidBlocks(text).length && base.themes) problems.push(...pairingProblems(root, f, text, undefined, base.themes));
  }
  if (base.theme && code && !lp.problems.length) {
    const sourceEntries = entries.filter((e) => e.header && !e.header.generated);
    const wantLineage = generateLineage(sourceEntries, base.theme, code);
    const lf = join(root, LINEAGE_FILE);
    if (!existsSync(lf) || readFileSync(lf, "utf8") !== wantLineage) problems.push({ file: LINEAGE_FILE, problem: "stale or missing: it is generated from the diagram headers (kit diagrams render); never edit it by hand" });
    const withLin = entriesWithLineage(root, code).map((e) => (e.file === LINEAGE_FILE ? { ...e, header: lineageHeader(code) } : e));
    const xf = join(root, INDEX_FILE);
    const projectName = projectOf(root, project, kit.registry)?.key;
    if (!existsSync(xf) || readFileSync(xf, "utf8") !== generateIndex(withLin, { projectName })) problems.push({ file: INDEX_FILE, problem: "stale, missing or hand-edited: the index is generated from the diagram headers (kit diagrams render)" });
  }
  return { theme: base.theme, problems, counts: { ...base.counts, ids: lp.ids.size }, project: pr };
}
